import{_ as t,o,c as r,ae as a}from"./chunks/framework.vXWZTEWX.js";const p=JSON.parse('{"title":"Simple Architecture Guide for TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"ARCHITECTURE_SIMPLE_GUIDE.md","filePath":"ARCHITECTURE_SIMPLE_GUIDE.md"}'),s={name:"ARCHITECTURE_SIMPLE_GUIDE.md"};function i(n,e,l,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="simple-architecture-guide-for-tendercheck-ai" tabindex="-1">Simple Architecture Guide for TenderCheck AI <a class="header-anchor" href="#simple-architecture-guide-for-tendercheck-ai" aria-label="Permalink to &quot;Simple Architecture Guide for TenderCheck AI&quot;">​</a></h1><p>Hello! As a software student, understanding the structure is the best way to learn. Here is a simplified breakdown of how our <strong>Clean Architecture</strong> backend works.</p><h2 id="_1-the-core-idea" tabindex="-1">1. The Core Idea <a class="header-anchor" href="#_1-the-core-idea" aria-label="Permalink to &quot;1. The Core Idea&quot;">​</a></h2><p>Imagine the application like an onion.</p><ul><li><strong>Inner Layers (Domain)</strong>: Pure business logic. They don&#39;t know about databases or API routes.</li><li><strong>Outer Layers (Infrastructure/Presentation)</strong>: The &quot;tools&quot; we use (Express, SQLite, etc.).</li></ul><h2 id="_2-your-questions-answered" tabindex="-1">2. Your Questions Answered <a class="header-anchor" href="#_2-your-questions-answered" aria-label="Permalink to &quot;2. Your Questions Answered&quot;">​</a></h2><h3 id="why-are-value-objects-and-interfaces-folders-empty" tabindex="-1">Why are <code>value-objects</code> and <code>interfaces</code> folders empty? <a class="header-anchor" href="#why-are-value-objects-and-interfaces-folders-empty" aria-label="Permalink to &quot;Why are `value-objects` and `interfaces` folders empty?&quot;">​</a></h3><p>It is correct for now!</p><ul><li><strong><code>domain/value-objects</code></strong>: Currently detailed validation rules for simple things (like <code>Email</code>, <code>Price</code>) are either handled with primitive types (<code>string</code>, <code>number</code>) or inside the entities. As the project grows and we need strict rules (e.g., &quot;Price cannot be negative&quot;), we will create specific classes here.</li><li><strong><code>application/interfaces</code></strong>: We define most interfaces directly in <code>domain</code> (business contracts) or within the implementation files for simplicity. Empty folders are often placeholders for future growth.</li></ul><h3 id="is-presentation-independent" tabindex="-1">Is <code>presentation</code> independent? <a class="header-anchor" href="#is-presentation-independent" aria-label="Permalink to &quot;Is `presentation` independent?&quot;">​</a></h3><p><strong>Yes!</strong></p><ul><li>The <strong>Presentation Layer</strong> (where Controllers and Routes live) is responsible for &quot;talking to the outside world&quot; (handling HTTP requests from the frontend).</li><li>It is a separate &quot;adapter&quot; layer. It depends on <code>application</code> to do the actual work, but <code>application</code> doesn&#39;t know it exists. This separation is key to Clean Architecture.</li></ul><h3 id="what-is-the-role-of-utils" tabindex="-1">What is the role of <code>utils</code>? <a class="header-anchor" href="#what-is-the-role-of-utils" aria-label="Permalink to &quot;What is the role of `utils`?&quot;">​</a></h3><p>Located in: <code>src/infrastructure/utils</code></p><ul><li><strong>Role</strong>: Helper tools that are technical, not business-related.</li><li><strong>Example</strong>: <code>safeExecute.ts</code> (helper to run code safely without crashing).</li><li><strong>Rule</strong>: If it&#39;s about &quot;Tenders&quot;, it goes in Domain. If it&#39;s about &quot;formatting a date string&quot; or &quot;try-catch blocks&quot;, it goes in Utils.</li></ul><h3 id="what-is-the-role-of-repositories" tabindex="-1">What is the role of <code>repositories</code>? <a class="header-anchor" href="#what-is-the-role-of-repositories" aria-label="Permalink to &quot;What is the role of `repositories`?&quot;">​</a></h3><p>They are the bridge between your code and the database.</p><ul><li><strong>In Domain (<code>domain/repositories</code>)</strong>: We define the <strong>Interface</strong> (The Contract). <ul><li><em>Example:</em> &quot;I need a <code>UserRepository</code> that has a <code>save()</code> method.&quot; (Doesn&#39;t care if it&#39;s SQL or JSON).</li></ul></li><li><strong>In Infrastructure (<code>infrastructure/repositories</code>)</strong>: We define the <strong>Implementation</strong> (The Code). <ul><li><em>Example:</em> &quot;Here is the <code>TursoTenderRepository</code> that uses SQL commands to save to the Turso database.&quot;</li></ul></li></ul><h2 id="_3-the-flow-of-request" tabindex="-1">3. The Flow of Request <a class="header-anchor" href="#_3-the-flow-of-request" aria-label="Permalink to &quot;3. The Flow of Request&quot;">​</a></h2><ol><li><strong>Presentation</strong>: Receives HTTP request -&gt; Calls Use Case.</li><li><strong>Application (Use Case)</strong>: Orchestrates the logic -&gt; Calls Domain/Repository.</li><li><strong>Domain</strong>: Enforces business rules.</li><li><strong>Infrastructure</strong>: Saves data to Database.</li></ol><p>This structure implies that you can change the Database (Infrastructure) or the API Framework (Presentation) without ever touching your Business Logic (Domain).</p>',21)])])}const f=t(s,[["render",i]]);export{p as __pageData,f as default};
